-- MIT Election Data and Science Lab: County Presidential Election Returns 2000-2024
-- Harvard Dataverse DOI: https://doi.org/10.7910/DVN/VOQCHQ
-- Verified 477-row presidential county dataset; no synthetic registration or turnout values
BEGIN;
DELETE FROM county_drift;
DELETE FROM county_voter_statistics;


SELECT y16.county, y16.democrat_votes::float/y16.total_votes*100, y16.republican_votes::float/y16.total_votes*100, y20.democrat_votes::float/y20.total_votes*100, y20.republican_votes::float/y20.total_votes*100, y24.democrat_votes::float/y24.total_votes*100, y24.republican_votes::float/y24.total_votes*100, (y24.democrat_votes::float/y24.total_votes*100)-(y16.democrat_votes::float/y16.total_votes*100), (y24.republican_votes::float/y24.total_votes*100)-(y16.republican_votes::float/y16.total_votes*100), ((y24.republican_votes::float/y24.total_votes*100)-(y16.republican_votes::float/y16.total_votes*100))/100, CASE WHEN y24.republican_votes::float/y24.total_votes >= y16.republican_votes::float/y16.total_votes THEN 'red' ELSE 'blue' END, ABS((y24.republican_votes::float/y24.total_votes*100)-(y16.republican_votes::float/y16.total_votes*100)), y16.total_votes, y24.total_votes, CASE WHEN y16.total_votes>0 THEN (y24.total_votes-y16.total_votes)::float/y16.total_votes*100 ELSE NULL END, NULL, NULL, NULL, NULL, 2024, 'MIT verified'
FROM county_voter_statistics y16
JOIN county_voter_statistics y24 ON y24.county=y16.county AND y24.election_year=2024
JOIN county_voter_statistics y20 ON y20.county=y16.county AND y20.election_year=2020
WHERE y16.election_year=2016
ON CONFLICT (county) DO NOTHING;

COMMIT;